1	// The ONE place the web app learns where the api lives. Everything that talks
2	// to the backend — the lobby WebSocket today, the full API client in the
3	// frontend-swap milestone — derives its URLs from here, so the origin is
4	// configured exactly once: `VITE_API_ORIGIN` at build time, falling back to
5	// `wrangler dev`'s default port for local development.
6	
7	const DEFAULT_API_ORIGIN = "http://localhost:8787";
8	
9	/** The api's http(s) origin, without a trailing slash. */
10	export function apiOrigin(): string {
11	  const configured = (import.meta.env.VITE_API_ORIGIN as string | undefined) ?? DEFAULT_API_ORIGIN;
12	  return configured.replace(/\/+$/, "");
13	}
14	
15	/** An absolute URL for an api route, e.g. `apiUrl("/lobby")`. */
16	export function apiUrl(path: string): string {
17	  return `${apiOrigin()}${path}`;
18	}
19	
20	/** The ws(s):// twin of `apiUrl`, for the api's WebSocket routes: http → ws
21	    and https → wss, same host, same path. */
22	export function apiWebSocketUrl(path: string): string {
23	  return apiUrl(path).replace(/^http/, "ws");
24	}
