1	/// <reference types="vitest/config" />
2	import react from "@vitejs/plugin-react";
3	import tailwindcss from "@tailwindcss/vite";
4	import { defineConfig, loadEnv, type Plugin } from "vite";
5	
6	// Content-Security-Policy for the production HTML only. It's injected at build
7	// time (not kept in index.html) so it can't strangle the dev server, whose HMR
8	// needs inline scripts, eval and a websocket. Allowlist: our own origin; the
9	// api origin (card/set images off its R2 asset mirror as <img> and Pixi
10	// textures, fetch for the api client, and its ws(s) twin for the lobby
11	// WebSocket); Google Fonts (stylesheet on googleapis, files on gstatic);
12	// data:/blob: for the SVG favicon, procedural card-back data-URLs and Pixi's
13	// bitmap decode. Inline styles are load-bearing (every animated transform is a
14	// style attribute), so style-src keeps 'unsafe-inline'; scripts do not (the
15	// build emits one external module, no inline script), so script-src stays
16	// tight. The api origin mirrors src/lib/apiOrigin.ts: `VITE_API_ORIGIN` (from
17	// the environment or a .env file, via loadEnv), falling back to wrangler dev's
18	// default port.
19	function buildCsp(apiOrigin: string): string {
20	  const apiWsOrigin = apiOrigin.replace(/^http/, "ws");
21	  return [
22	    "default-src 'self'",
23	    "script-src 'self'",
24	    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
25	    "font-src 'self' https://fonts.gstatic.com",
26	    `img-src 'self' data: blob: ${apiOrigin}`,
27	    `connect-src 'self' ${apiOrigin} ${apiWsOrigin}`,
28	    "worker-src 'self' blob:",
29	    "object-src 'none'",
30	    "base-uri 'self'",
31	    "form-action 'self'",
32	  ].join("; ");
33	}
34	
35	function cspPlugin(csp: string): Plugin {
36	  return {
37	    name: "html-csp",
38	    apply: "build",
39	    transformIndexHtml(html) {
40	      return html.replace(
41	        "<head>",
42	        `<head>\n    <meta http-equiv="Content-Security-Policy" content="${csp}" />`,
43	      );
44	    },
45	  };
46	}
47	
48	export default defineConfig(({ mode }) => {
49	  const env = loadEnv(mode, process.cwd());
50	  const apiOrigin = (env.VITE_API_ORIGIN ?? "http://localhost:8787").replace(/\/+$/, "");
51	  return {
52	    plugins: [react(), tailwindcss(), cspPlugin(buildCsp(apiOrigin))],
53	    test: {
54	      // Default to the fast Node environment for the pure-logic suites (reducers,
55	      // deck/z-index math, parsing). Component/DOM tests opt into jsdom per file
56	      // with a `// @vitest-environment jsdom` docblock — see the *.dom.test.tsx
57	      // files (React Testing Library), so the many pure tests keep the lean env.
58	      environment: "node",
59	      include: [
60	        "src/**/*.{test,spec}.{ts,tsx}",
61	        "apps/*/src/**/*.{test,spec}.{ts,tsx}",
62	        "packages/*/src/**/*.{test,spec}.{ts,tsx}",
63	      ],
64	    },
65	    build: {
66	      // Match the TypeScript target so output isn't down-levelled further than needed.
67	      target: "es2022",
68	      // Emit source maps but don't reference them from the bundles ("hidden"), so
69	      // production stack traces stay resolvable (error reporting) without shipping
70	      // a //# sourceMappingURL that exposes source in end-users' devtools.
71	      sourcemap: "hidden",
72	      rollupOptions: {
73	        output: {
74	          // Split the large, rarely-changing vendor libs into their own chunks so
75	          // an app-code edit doesn't bust the Pixi/GSAP/React cache entries.
76	          manualChunks(id: string) {
77	            if (!id.includes("node_modules")) return undefined;
78	            if (id.includes("/pixi.js")) return "pixi";
79	            if (id.includes("/gsap")) return "gsap";
80	            if (id.includes("/react") || id.includes("/scheduler")) return "react";
81	            return undefined;
82	          },
83	        },
84	      },
85	    },
86	  };
87	});
